import sys
input = sys.stdin.read

def find_minimum_time_to_prepare_potions():
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])
    x = int(data[3])
    s = int(data[4])

    a = list(map(int, data[5:m+5]))
    b = list(map(int, data[m+5:2*m+5]))
    c = list(map(int, data[2*m+5:2*m+5+k]))
    d = list(map(int, data[2*m+5+k:2*m+5+2*k]))

    min_time = n * x

    for i in range(m):
        if b[i] <= s:
            min_time = min(min_time, n * a[i])

    for i in range(k):
        if d[i] <= s:
            potions_left = n - c[i]
            if potions_left <= 0:
                min_time = 0
            else:
                min_time = min(min_time, potions_left * x)

    for i in range(m):
        if b[i] <= s:
            effective_time_per_potion = a[i]
            left, right = 0, k - 1
            best_c = 0
            while left <= right:
                mid = (left + right) // 2
                if b[i] + d[mid] <= s:
                    best_c = c[mid]
                    left = mid + 1
                else:
                    right = mid - 1

            potions_left = n - best_c
            if potions_left <= 0:
                min_time = 0
            else:
                min_time = min(min_time, potions_left * effective_time_per_potion)

    print(min_time)

